class Manacher:
    def __init__(self,input_string): self.input_string=input_string
    def palindromic_length(self, center, diff, string):
        if center-diff<0 or center+diff>=len(string) or string[center-diff]!=string[center+diff]: return diff-1
        return self.palindromic_length(center,diff+1,string)
    def palindromic_string(self):
        transformed='|'.join(self.input_string)
        max_length=0; center=0
        for i in range(len(transformed)):
            length=self.palindromic_length(i,1,transformed)
            if length>max_length: max_length=length; center=i
        return ''.join(transformed[center-max_length:center+max_length+1].split('|'))
